function renderVehicles(){var rows=(DATA.vehicles||[]).slice().sort(function(a,b){return String(a.vehicle_name).localeCompare(String(b.vehicle_name));});$('vehicleCards').innerHTML=rows.map(function(v){var color=v.vehicle_status==='maintenance'?'#ef4444':v.vehicle_status==='inactive'?'#64748b':'#10b981';return'<article class="vehicle-card" style="--vehicle-color:'+color+'"><div class="vehicle-title"><div><h4>'+esc(v.vehicle_name)+'</h4><p>'+esc(v.plate_number)+' — '+esc(v.vehicle_brand||v.vehicle_type||'')+'</p></div><span class="badge">'+esc(v.vehicle_status||'available')+'</span></div><div class="vehicle-stats"><div class="vehicle-stat"><span>'+esc(lang()==='ar'?'السائق':'Driver')+'</span><b>'+esc(v.current_driver_name||'—')+'</b></div><div class="vehicle-stat"><span>'+esc(lang()==='ar'?'السعة':'Capacity')+'</span><b>'+n(v.capacity_passengers)+'</b></div><div class="vehicle-stat"><span>'+esc(lang()==='ar'?'الموقع الحالي':'Location')+'</span><b>'+esc(v.current_location||'—')+'</b></div><div class="vehicle-stat"><span>'+esc(lang()==='ar'?'ميعاد التحرك':'Departure')+'</span><b>'+esc(v.default_departure_time||'—')+'</b></div></div><div class="meta-row"><span>'+esc(v.default_route||'—')+'</span><button class="btn small ghost" data-action="edit-vehicle" data-id="'+esc(v.vehicle_id)+'">✎</button></div></article>';}).join('')||'<div class="stack-item"><p>'+esc(lang()==='ar'?'لا توجد سيارات.':'No vehicles.')+'</p></div>';}
